DELIMITER //

CREATE PROCEDURE SumOfDigits(IN num INT)
BEGIN
    DECLARE total INT DEFAULT 0;
    DECLARE remainder INT;

    WHILE num > 0 DO
        SET remainder = MOD(num, 10);
        SET total = total + remainder;
        SET num = FLOOR(num / 10);
    END WHILE;

    SELECT 'Result' AS '';
    SELECT CONCAT('Sum of digits is: ', total) AS '';
END //

DELIMITER ;

