CREATE PROCEDURE FindGreatest(IN n1 INT, IN n2 INT, IN n3 INT)
BEGIN
    DECLARE greatest INT;

    IF n1 >= n2 AND n1 >= n3 THEN
        SET greatest = n1;
    ELSEIF n2 >= n1 AND n2 >= n3 THEN
        SET greatest = n2;
    ELSE
        SET greatest = n3;
    END IF;

    SELECT 'Result' AS '';
    SELECT CONCAT('The greatest number is: ', greatest) AS '';
END //

